begin;
-- LC editorial migration — módulo 3: Decisões
update nexora.lessons set objective='Reconhecer quando uma regra exige uma decisão e expressar a condição que separa os caminhos possíveis usando um resultado booleano claro.',estimated_minutes=21,content='[{"type":"story","title":"Nem todo dado produz sempre o mesmo caminho","body":"Um sistema de cinema recebe a idade de uma pessoa. Para algumas idades, a venda é permitida; para outras, precisa ser bloqueada. A entrada continua sendo um número, mas agora o algoritmo precisa escolher o que fazer com base nele.\n\nDecisões aparecem quando a mesma sequência não serve para todos os casos."},{"type":"concept","title":"Condição é a pergunta que escolhe o caminho","body":"Uma condição é uma expressão que resulta em verdadeiro ou falso. O algoritmo usa esse resultado para decidir qual conjunto de passos executar.\n\n`idade >= 18` não diz ainda o que fazer; apenas responde uma pergunta. A decisão nasce quando associamos cada resultado a um comportamento."},{"type":"example","title":"Classificação etária simples","body":"Regra: permitir a compra quando idade >= 18.\n\nIdade 20 → condição verdadeira → permitir.\nIdade 17 → condição falsa → bloquear.\nIdade 18 → condição verdadeira → permitir.\n\nO teste com 18 confirma se a fronteira foi modelada corretamente."},{"type":"mechanics","title":"Antes de escrever a decisão, responda","items":["Qual é a pergunta booleana?","O que deve acontecer quando ela for verdadeira?","O que deve acontecer quando ela for falsa?","Existe um valor de fronteira que merece teste?"]},{"type":"guided","title":"Encontre a condição, não a ação","question":"A regra diz: “pedidos com total de R$ 200 ou mais têm frete grátis”. Qual é a condição?","options":["Mostrar frete grátis.","total >= 200","Cobrar R$ 20.","Calcular o carrinho."],"answer":1,"feedback":"Correto. A condição é a pergunta booleana que separa os caminhos.","feedback_incorrect":"Procure a expressão que pode resultar apenas em verdadeiro ou falso."},{"type":"mistake","title":"Não esconda a regra dentro do efeito","body":"Frases como “se for bom, aprove” ainda são vagas. A condição precisa ser observável e testável: `nota >= 7`, `saldo >= valorCompra`, `status == \"ativo\"`."},{"type":"recap","items":["Decisões escolhem caminhos diferentes para situações diferentes.","A condição é uma expressão booleana.","Cada resultado precisa estar associado a uma ação clara.","Fronteiras devem ser testadas."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Decisões","concept":"Reconhecer quando uma regra exige uma decisão e expressar a condição que separa os caminhos possíveis usando um resultado booleano claro.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual condição representa “aprovar quando a nota for 7 ou maior”?","options":["nota > 7","nota >= 7","nota < 7","nota == 0"],"answer":1,"feedback":"Correto. O próprio 7 precisa ser incluído.","feedback_incorrect":"A expressão deve aceitar exatamente 7 e qualquer valor acima."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=1;
update nexora.lessons set objective='Construir decisões de dois caminhos com SE e SENÃO, garantindo que as alternativas sejam mutuamente compreensíveis e cubram todos os resultados esperados da condição.',estimated_minutes=24,content='[{"type":"story","title":"Quando a resposta só pode seguir por dois caminhos","body":"Uma venda pode estar autorizada ou recusada. Um aluno pode estar aprovado ou em recuperação segundo uma regra simples. Um pedido pode ter frete grátis ou frete pago.\n\nQuando uma condição divide o problema em dois comportamentos complementares, SE e SENÃO formam uma estrutura natural."},{"type":"concept","title":"SE trata o verdadeiro; SENÃO trata o restante","body":"O bloco SE executa quando a condição é verdadeira. O SENÃO executa quando ela é falsa. Como a condição só pode ter dois resultados, a estrutura cobre os dois caminhos.\n\nIsso é diferente de escrever duas condições independentes, que podem se sobrepor ou deixar lacunas."},{"type":"example","title":"Frete grátis a partir de R$ 200","body":"SE valorPedido >= 200\n    frete = 0\nSENÃO\n    frete = 20\nFIM\n\nPara 199, o algoritmo escolhe o SENÃO. Para 200 e 201, escolhe o SE."},{"type":"comparison","title":"Dois IFs separados podem ser mais difíceis de provar","body":"Se você escreve uma condição para “>= 200” e outra para “< 200”, as duas são complementares, mas o leitor precisa verificar isso. SE/SENÃO deixa explícito que exatamente um dos caminhos será escolhido."},{"type":"guided","title":"Qual caminho será executado?","question":"Na regra `SE saldo >= compra SENÃO`, com saldo=100 e compra=120, qual bloco executa?","options":["SE","SENÃO","Os dois","Nenhum"],"answer":1,"feedback":"Correto. 100 >= 120 é falso, portanto o SENÃO é executado.","feedback_incorrect":"Calcule primeiro o resultado booleano da condição."},{"type":"mistake","title":"SENÃO não significa “erro”","body":"O caminho falso pode representar uma situação perfeitamente válida. Em uma classificação, por exemplo, “não premium” não é erro; é apenas a outra categoria."},{"type":"recap","items":["SE executa o caminho verdadeiro.","SENÃO executa quando a condição é falsa.","A estrutura é ideal para alternativas complementares.","Calcule mentalmente a condição antes de prever o caminho."]}]'::jsonb,lab_type='pseudocode',lab_config='{"module":"Decisões","concept":"Construir decisões de dois caminhos com SE e SENÃO, garantindo que as alternativas sejam mutuamente compreensíveis e cubram todos os resultados esperados da condição.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Uma regra define: `SE idade >= 18: adulto; SENÃO: menor`. Para idade=18, qual resultado ocorre?","options":["menor","adulto","erro","nenhum"],"answer":1,"feedback":"Correto. A comparação inclui o valor 18.","feedback_incorrect":"Observe que a condição usa maior ou igual."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=2;
update nexora.lessons set objective='Modelar regras com três ou mais faixas usando uma cadeia ordenada de condições, evitando sobreposição e garantindo que cada valor caia na categoria correta.',estimated_minutes=23,content='[{"type":"story","title":"Duas opções nem sempre bastam","body":"Uma escola pode classificar desempenho como excelente, aprovado, recuperação ou reprovado. Uma única condição não representa quatro faixas. Também não queremos testar todas as regras como se fossem independentes.\n\nQuando existem várias alternativas exclusivas, uma cadeia de condições organiza a escolha."},{"type":"concept","title":"SENÃO SE testa a próxima possibilidade apenas se as anteriores falharem","body":"A ordem das condições importa. Se começarmos pela faixa mais ampla, ela pode capturar valores que deveriam pertencer a uma faixa mais específica.\n\nPara notas, podemos testar primeiro a maior faixa e descer: >=9, depois >=7, depois >=5, e finalmente o SENÃO."},{"type":"example","title":"Classificação por nota","body":"SE nota >= 9 → Excelente\nSENÃO SE nota >= 7 → Aprovado\nSENÃO SE nota >= 5 → Recuperação\nSENÃO → Reprovado\n\nNota 8 falha no primeiro teste e passa no segundo. Os testes seguintes nem precisam ser avaliados."},{"type":"mechanics","title":"Revise a cadeia como intervalos","items":["Cada faixa deve ter início e fim compreensíveis.","A ordem precisa evitar que uma condição ampla capture valores cedo demais.","O SENÃO final pode funcionar como faixa restante.","Teste um valor dentro de cada faixa e todos os limites."]},{"type":"guided","title":"A ordem pode mudar tudo","question":"Se a primeira condição for `nota >= 5` e depois vier `nota >= 9`, o que acontece com nota 10?","options":["Cai em >=9.","Cai em >=5 antes de chegar ao teste >=9.","Executa as duas faixas.","Nenhuma condição é verdadeira."],"answer":1,"feedback":"Correto. A primeira condição verdadeira encerra a cadeia.","feedback_incorrect":"Em uma cadeia, condições posteriores só são testadas quando as anteriores falham."},{"type":"mistake","title":"Faixas sobrepostas geram classificações erradas","body":"Uma condição correta isoladamente pode estar errada na posição em que foi colocada. Sempre analise a cadeia completa como um sistema de intervalos."},{"type":"recap","items":["SENÃO SE permite várias alternativas exclusivas.","A primeira condição verdadeira define o caminho.","Ordem é parte da regra.","Teste todas as faixas e seus limites."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Decisões","concept":"Modelar regras com três ou mais faixas usando uma cadeia ordenada de condições, evitando sobreposição e garantindo que cada valor caia na categoria correta.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Para classificar idade em criança (<12), adolescente (<18) e adulto, qual ordem é mais segura?","options":["idade < 18; depois idade < 12; SENÃO","idade < 12; depois idade < 18; SENÃO","idade >= 0; depois idade < 18","SENÃO antes de qualquer condição"],"answer":1,"feedback":"Correto. A faixa mais restrita precisa ser testada antes da faixa mais ampla.","feedback_incorrect":"Se testar <18 primeiro, crianças também serão capturadas como adolescentes."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=3;
update nexora.lessons set objective='Combinar comparações com operadores lógicos para representar regras de decisão compostas sem duplicar caminhos ou perder clareza.',estimated_minutes=24,content='[{"type":"story","title":"Uma aprovação pode depender de mais de um requisito","body":"Uma empresa aprova um cadastro somente se o documento estiver válido E a pessoa tiver 18 anos ou mais. Não basta testar uma condição e esquecer a outra.\n\nCondições compostas permitem que uma decisão reflita múltiplos requisitos de uma vez."},{"type":"concept","title":"A condição composta continua produzindo um único booleano","body":"Mesmo contendo várias comparações, a expressão final precisa resultar em verdadeiro ou falso. `idade >= 18 E documentoValido` é uma única pergunta lógica.\n\nO desafio é traduzir corretamente a linguagem da regra para E, OU e NÃO."},{"type":"example","title":"Benefício por perfil","body":"Regra: conceder benefício se clienteAtivo E (planoPremium OU comprasAno >= 5000).\n\nOs parênteses mostram que primeiro avaliamos duas formas alternativas de qualificação; depois exigimos também que o cliente esteja ativo."},{"type":"comparison","title":"Agrupamentos diferentes representam regras diferentes","body":"`ativo E premium OU altoGasto` pode ser lido de forma diferente de `ativo E (premium OU altoGasto)`. Quando a regra mistura E e OU, use parênteses mesmo que a linguagem tenha precedência definida. Clareza faz parte da correção."},{"type":"guided","title":"Traduza a frase","question":"“Entrar se tiver convite OU se for funcionário.” Qual expressão representa a regra?","options":["convite E funcionario","convite OU funcionario","NÃO convite","convite E NÃO funcionario"],"answer":1,"feedback":"Correto. Qualquer uma das duas condições é suficiente.","feedback_incorrect":"A palavra “ou” indica alternativas; não é necessário satisfazer as duas."},{"type":"mistake","title":"Evite repetir o mesmo efeito em vários IFs","body":"Se dois caminhos diferentes levam à mesma ação, muitas vezes é mais claro combinar as condições com OU do que duplicar o bloco de ação. Isso reduz repetição e risco de divergência."},{"type":"recap","items":["Condições compostas combinam booleanos.","E exige todos; OU aceita alternativas; NÃO inverte.","Parênteses documentam agrupamentos.","Uma regra clara reduz duplicação de caminhos."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Decisões","concept":"Combinar comparações com operadores lógicos para representar regras de decisão compostas sem duplicar caminhos ou perder clareza.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Um desconto vale para cliente VIP OU compra acima de R$ 1000. Qual cenário NÃO recebe desconto?","options":["VIP e compra 200","Não VIP e compra 1500","VIP e compra 1500","Não VIP e compra 500"],"answer":3,"feedback":"Correto. Nenhuma das duas condições é verdadeira.","feedback_incorrect":"Com OU, basta uma condição verdadeira para conceder o desconto."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=4;
update nexora.lessons set objective='Usar decisões aninhadas apenas quando uma segunda pergunta realmente depende do primeiro caminho, comparando essa abordagem com condições compostas mais simples.',estimated_minutes=23,content='[{"type":"story","title":"Algumas perguntas só fazem sentido depois de outra","body":"Imagine um sistema de saque. Primeiro precisamos verificar se a conta está ativa. Somente se estiver, faz sentido verificar se há saldo suficiente. A segunda decisão depende da primeira.\n\nEsse é um caso natural de aninhamento: uma decisão dentro do caminho de outra."},{"type":"concept","title":"Aninhar é criar uma decisão dentro de um caminho já escolhido","body":"Aninhamento representa dependência entre perguntas. Porém, cada nível extra aumenta a carga de leitura. Quando as condições podem ser combinadas de forma clara, uma expressão composta pode ser melhor."},{"type":"example","title":"Saque em duas etapas","body":"SE contaAtiva\n    SE saldo >= valorSaque\n        autorizar\n    SENÃO\n        informar saldo insuficiente\nSENÃO\n    informar conta inativa\n\nA mensagem de erro depende de qual requisito falhou."},{"type":"comparison","title":"Aninhamento ou condição composta?","body":"Se só precisamos saber “pode sacar ou não”, `contaAtiva E saldo >= valorSaque` pode bastar. Se precisamos responder de forma diferente para conta inativa e saldo insuficiente, o aninhamento torna os motivos explícitos."},{"type":"guided","title":"Quando aninhar ajuda?","question":"Qual situação justifica melhor uma decisão dentro de outra?","options":["Mostrar a mesma mensagem para qualquer falha.","Primeiro validar login e, somente se válido, verificar permissão específica.","Somar dois números.","Percorrer uma lista."],"answer":1,"feedback":"Correto. A segunda pergunta depende de passar pela primeira etapa.","feedback_incorrect":"Procure um cenário em que uma segunda verificação só faz sentido após a primeira."},{"type":"mistake","title":"Pirâmide de IFs é sinal de revisão","body":"Muitos níveis de aninhamento tornam caminhos difíceis de visualizar. Decomponha a regra, use retornos antecipados quando a linguagem permitir ou crie condições nomeadas."},{"type":"recap","items":["Aninhamento representa dependência entre decisões.","Nem toda condição composta precisa ser aninhada.","Mensagens e efeitos diferentes podem justificar caminhos separados.","Muitos níveis indicam necessidade de simplificação."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Decisões","concept":"Usar decisões aninhadas apenas quando uma segunda pergunta realmente depende do primeiro caminho, comparando essa abordagem com condições compostas mais simples.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Se precisamos informar separadamente “conta inativa” e “saldo insuficiente”, qual estrutura ajuda mais?","options":["Uma soma.","Uma decisão aninhada ou sequência de validações que preserve o motivo da falha.","Um laço infinito.","Uma constante booleana única sem testes."],"answer":1,"feedback":"Correto. Precisamos preservar qual requisito falhou.","feedback_incorrect":"A estrutura deve permitir resultados diferentes para causas diferentes."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=5;
update nexora.lessons set objective='Prever resultados de condições compostas por meio de tabelas de casos, usando combinações sistemáticas para validar regras com E, OU e NÃO.',estimated_minutes=22,content='[{"type":"story","title":"Quatro combinações podem revelar um bug invisível","body":"Se uma regra depende de duas condições booleanas, existem quatro combinações possíveis: verdadeiro/verdadeiro, verdadeiro/falso, falso/verdadeiro e falso/falso. Testar apenas uma delas é confiar demais na intuição.\n\nUma tabela-verdade prática organiza essas combinações e mostra o resultado esperado."},{"type":"concept","title":"Tabela-verdade é uma ferramenta de teste","body":"Você não precisa decorar uma tabela formal para sempre. O valor está em listar combinações e perguntar qual deveria ser o resultado da regra em cada uma.\n\nPara `A E B`, somente verdadeiro/verdadeiro produz verdadeiro. Para `A OU B`, somente falso/falso produz falso."},{"type":"example","title":"Acesso: autenticado E autorizado","body":"Autenticado=true, autorizado=true → permitir.\nAutenticado=true, autorizado=false → negar.\nAutenticado=false, autorizado=true → negar.\nAutenticado=false, autorizado=false → negar.\n\nSe algum desses resultados divergir na implementação, a regra está errada."},{"type":"mechanics","title":"Use combinações como casos de teste","items":["Liste as condições booleanas da regra.","Monte todas as combinações quando forem poucas.","Escreva o resultado esperado antes de executar.","Compare com o comportamento observado.","Quando houver muitas condições, priorize combinações de fronteira e riscos."]},{"type":"guided","title":"Resultado de OU","question":"Para `temCupom OU clienteVIP`, qual combinação produz falso?","options":["true / true","true / false","false / true","false / false"],"answer":3,"feedback":"Correto. OU só é falso quando nenhuma condição é verdadeira.","feedback_incorrect":"Com OU, qualquer verdadeiro já torna a expressão verdadeira."},{"type":"professional_context","title":"Isso vira estratégia de teste em sistemas reais","body":"Matrizes de decisão e testes parametrizados seguem a mesma ideia: variar entradas e verificar resultados esperados. A tabela-verdade é uma primeira forma de pensar sistematicamente sobre cobertura."},{"type":"recap","items":["Condições booleanas têm combinações finitas.","Listar combinações reduz suposições.","Resultado esperado deve ser definido antes da execução.","Tabelas de casos aproximam lógica de programação e testes."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Decisões","concept":"Prever resultados de condições compostas por meio de tabelas de casos, usando combinações sistemáticas para validar regras com E, OU e NÃO.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Para a regra `ativo E (premium OU altoGasto)`, qual cenário deve ser falso?","options":["ativo=true, premium=true, altoGasto=false","ativo=true, premium=false, altoGasto=true","ativo=false, premium=true, altoGasto=true","ativo=true, premium=true, altoGasto=true"],"answer":2,"feedback":"Correto. Mesmo qualificado por premium ou gasto, o cliente inativo falha no E externo.","feedback_incorrect":"Avalie primeiro o agrupamento e depois combine com a condição `ativo`."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=6;
update nexora.lessons set objective='Construir decisões robustas tratando explicitamente dados ausentes, inválidos e fora do domínio antes de aplicar a regra principal.',estimated_minutes=25,content='[{"type":"story","title":"O mundo real envia dados que a aula perfeita não envia","body":"Uma idade pode chegar vazia. Uma nota pode ser 15 por erro de digitação. Um status pode ter valor desconhecido. Se a decisão assume que toda entrada é válida, o resultado pode ser silenciosamente incorreto.\n\nUma decisão robusta não pensa apenas no caminho feliz; ela protege a regra contra dados que não deveriam ser processados."},{"type":"concept","title":"Validação vem antes da classificação","body":"Antes de perguntar “é maior de idade?”, precisamos saber se a idade existe, é numérica e está em um domínio plausível. Só depois aplicamos a regra principal.\n\nIsso separa duas responsabilidades: validar o dado e decidir com base em um dado válido."},{"type":"example","title":"Nota escolar com validação","body":"Primeiro: se nota estiver ausente → informar campo obrigatório.\nDepois: se nota < 0 OU nota > 10 → informar valor inválido.\nSomente então: classificar como aprovado, recuperação ou reprovado.\n\nUma nota 15 não deve ser classificada como “excelente”; deve ser rejeitada como entrada inválida."},{"type":"comparison","title":"Fallback não é esconder erro","body":"Um SENÃO final pode tratar casos restantes, mas não deve transformar dados inválidos em uma categoria legítima. Quando a entrada viola o domínio, o resultado correto pode ser interromper a decisão e informar o problema."},{"type":"guided","title":"Valide antes de decidir","question":"Uma idade chega como -3. O que deve acontecer antes de avaliar `idade >= 18`?","options":["Classificar como menor de idade.","Rejeitar ou sinalizar a entrada como inválida.","Converter para 3 automaticamente.","Aprovar porque existe um número."],"answer":1,"feedback":"Correto. O valor está fora do domínio esperado e não deve entrar na classificação normal.","feedback_incorrect":"Uma entrada pode ser numericamente comparável e ainda assim ser inválida para o domínio."},{"type":"mastery","title":"Uma decisão está madura quando você consegue explicar","items":["Qual dado é validado antes da regra.","Quais são os caminhos legítimos.","Quais são as fronteiras.","O que acontece com ausência e valor inválido.","Quais casos de teste cobrem cada caminho."]},{"type":"recap","items":["Validação deve preceder decisões de negócio.","Dado ausente e dado inválido são casos diferentes.","Fallback não deve mascarar erro de domínio.","Decisões robustas incluem caminhos de falha previsíveis."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Decisões","concept":"Construir decisões robustas tratando explicitamente dados ausentes, inválidos e fora do domínio antes de aplicar a regra principal.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual sequência é mais segura para classificar uma nota?","options":["Classificar → validar depois.","Verificar presença → validar faixa 0–10 → aplicar regras de classificação.","Aplicar SENÃO para qualquer valor.","Converter todo valor inválido para zero."],"answer":1,"feedback":"Correto. Primeiro garantimos que o dado pode participar da regra.","feedback_incorrect":"A classificação só é confiável depois que a entrada foi validada."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=7;
update nexora.questions set prompt='Qual condição representa corretamente “aprovar quando nota for 7 ou maior”?',options='[{"id":"a","label":"nota > 7"},{"id":"b","label":"nota >= 7"},{"id":"c","label":"nota < 7"},{"id":"d","label":"nota == 0"}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. O valor 7 precisa ser incluído.',feedback_incorrect='Observe a fronteira descrita pela palavra “ou maior”.',difficulty=1 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) order by a.created_at asc limit 1) and position=1;
update nexora.questions set prompt='Em `SE saldo >= compra SENÃO`, com saldo=80 e compra=100, qual caminho executa?',options='[{"id":"a","label":"SE"},{"id":"b","label":"SENÃO"},{"id":"c","label":"Os dois"},{"id":"d","label":"Nenhum"}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. A condição é falsa.',feedback_incorrect='Calcule primeiro 80 >= 100.',difficulty=1 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) order by a.created_at asc limit 1) and position=2;
update nexora.questions set prompt='Por que a ordem importa em uma cadeia SENÃO SE?',options='[{"id":"a","label":"Porque a primeira condição verdadeira define o caminho."},{"id":"b","label":"Porque todas as condições sempre executam."},{"id":"c","label":"Porque a ordem só muda a formatação."},{"id":"d","label":"Porque SENÃO SE ignora booleanos."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. Uma condição ampla colocada cedo pode capturar valores indevidos.',feedback_incorrect='Pense no que acontece depois que uma condição da cadeia é verdadeira.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) order by a.created_at asc limit 1) and position=3;
update nexora.questions set prompt='Qual expressão representa “ativo e (premium ou gasto alto)”?',options='[{"id":"a","label":"ativo OU premium E gastoAlto"},{"id":"b","label":"ativo E (premium OU gastoAlto)"},{"id":"c","label":"NÃO ativo E premium"},{"id":"d","label":"ativo E premium E gastoAlto"}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. O agrupamento representa as alternativas de qualificação dentro da exigência de ativo.',feedback_incorrect='Separe a exigência obrigatória das duas alternativas.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) order by a.created_at asc limit 1) and position=4;
update nexora.questions set prompt='Quando o aninhamento é especialmente útil?',options='[{"id":"a","label":"Quando uma segunda verificação só faz sentido depois da primeira."},{"id":"b","label":"Para toda soma."},{"id":"c","label":"Sempre que houver uma variável."},{"id":"d","label":"Para substituir qualquer laço."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. A dependência entre perguntas justifica o aninhamento.',feedback_incorrect='Procure um cenário em que o segundo teste depende do primeiro.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) order by a.created_at asc limit 1) and position=5;
update nexora.questions set prompt='Para `A OU B`, qual combinação resulta em falso?',options='[{"id":"a","label":"true/true"},{"id":"b","label":"true/false"},{"id":"c","label":"false/true"},{"id":"d","label":"false/false"}]'::jsonb,correct_answer='{"option_id":"d"}'::jsonb,feedback_correct='Correto. OU só falha quando nenhuma condição é verdadeira.',feedback_incorrect='Basta um verdadeiro para o operador OU produzir verdadeiro.',difficulty=3 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) order by a.created_at asc limit 1) and position=6;
insert into nexora.questions(id,assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position)
select gen_random_uuid(),(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) order by a.created_at asc limit 1),'Uma nota chega como 15 em um sistema que aceita apenas 0 a 10. Qual deve ser o primeiro resultado?','multiple_choice','[{"id":"a","label":"Aprovado."},{"id":"b","label":"Excelente."},{"id":"c","label":"Entrada inválida."},{"id":"d","label":"Recuperação."}]'::jsonb,'{"option_id":"c"}'::jsonb,'Correto. O domínio precisa ser validado antes da classificação.','Não classifique um valor que viola a faixa válida.',3,7
where not exists(select 1 from nexora.questions where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) order by a.created_at asc limit 1) and position=7);
update nexora.assessments set title='Checkpoint aplicado — Decisões',pass_score=70,max_attempts=3 where id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) order by a.created_at asc limit 1);
update nexora.learning_resources set title='Apostila LC — Decisões',summary='Revisão integrada de condições, caminhos, faixas, lógica composta e validação de entradas.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"1. Condições escolhem caminhos","body":"Uma condição é uma expressão booleana. A decisão associa resultado verdadeiro e falso a comportamentos observáveis."},{"title":"2. SE/SENÃO cobre alternativas complementares","body":"Quando existem dois caminhos, a estrutura deixa explícito que exatamente um deles será executado."},{"title":"3. Cadeias organizam várias faixas","body":"SENÃO SE testa alternativas em ordem. Faixas mais específicas precisam vir antes de faixas mais amplas."},{"title":"4. Condições compostas traduzem regras reais","body":"E, OU e NÃO combinam comparações. Parênteses tornam agrupamentos claros."},{"title":"5. Aninhamento representa dependência","body":"Use quando uma segunda pergunta depende do primeiro caminho ou quando é necessário preservar motivos diferentes de falha."},{"title":"6. Tabelas de casos ajudam a testar","body":"Liste combinações de booleanos e escreva resultados esperados antes de executar."},{"title":"7. Valide antes de classificar","body":"Ausência, formato e domínio devem ser tratados antes da regra de negócio."},{"title":"Exercícios","items":["Crie uma regra de aprovação com três faixas.","Modele um desconto que dependa de duas condições.","Monte uma tabela de casos para acesso autenticado/autorizado.","Adicione tratamento para dados ausentes e inválidos."]}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=1;
update nexora.learning_resources set title='Guia de revisão de decisões',summary='Checklist para revisar caminhos e condições antes de considerar uma regra concluída.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"Checklist","items":["A condição produz booleano?","Os limites usam operadores corretos?","Todas as faixas são cobertas sem sobreposição indevida?","E/OU representam a frase original?","Existe aninhamento desnecessário?","Dados inválidos são tratados antes?","Há caso de teste para cada caminho?"]},{"title":"Sinais de alerta","items":["Muitos IFs com o mesmo efeito.","Vários níveis de aninhamento.","SENÃO usado para esconder qualquer erro.","Condição ampla antes de condição específica.","Nenhum teste exatamente na fronteira."]}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=2;
update nexora.learning_resources set title='Desafio aplicado — Política de aprovação',summary='Atividade integradora para criar uma decisão robusta com faixas, requisitos compostos e validação.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"Cenário","body":"Modele uma política de aprovação escolar usando nota, frequência e situação documental. A nota deve estar entre 0 e 10 e a frequência entre 0 e 100."},{"title":"Requisitos","items":["Rejeite dados ausentes ou fora do domínio.","Crie pelo menos três resultados acadêmicos.","Inclua ao menos uma condição composta.","Explique a ordem das faixas.","Crie casos normais, fronteiras e inválidos."]},{"title":"Critério","body":"Cada caminho precisa ser justificável a partir das condições e reproduzível com os casos de teste."}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=3;
commit;
